-- Streaming descriptions: the customer receives a ready account (no email needed). Only rows still holding the starter text change.
UPDATE "Product" SET "description" = '{"ht": "Ou resevwa yon kont Netflix pare pou itilize: imèl ak modpas parèt sou paj kòmand ou. Ou pa bezwen bay anyen.", "fr": "Vous recevez un compte Netflix prêt à l''emploi : l''e-mail et le mot de passe s''affichent sur la page de votre commande. Rien à fournir.", "en": "You get a ready-to-use Netflix account: the email and password appear on your order page. Nothing to provide.", "es": "Recibes una cuenta de Netflix lista para usar: el correo y la contraseña aparecen en la página de tu pedido. No tienes que dar nada."}'::jsonb WHERE "slug" = 'netflix-subscription' AND "description"->>'ht' = 'Nou aktive abònman an sou imèl kont ou. Ekip nou an ap kontakte w si nou bezwen plis enfòmasyon.';
UPDATE "Product" SET "description" = '{"ht": "Mizik san piblisite. Ou resevwa yon kont Spotify pare: imèl ak modpas parèt sou paj kòmand ou.", "fr": "Musique sans publicité. Vous recevez un compte Spotify prêt : e-mail et mot de passe sur la page de votre commande.", "en": "Ad-free music. You get a ready Spotify account: email and password on your order page.", "es": "Música sin anuncios. Recibes una cuenta de Spotify lista: correo y contraseña en la página de tu pedido."}'::jsonb WHERE "slug" = 'spotify-premium' AND "description"->>'ht' = 'Mizik san piblisite. Nou aktive l sou imèl kont ou.';
